import { MeshStandardNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { Group, Mesh, PlaneGeometry } from '@/primitives';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // Create container
  const container = new Group();

  // Geometry (small capsule label)
  const width = 0.8;
  const height = 0.3;
  const geometry = new PlaneGeometry(width, height);

  // Material placeholder
  const material = new MeshStandardNodeMaterial({
    color: 0xffffff,
    roughness: 0.6,
    metalness: 0.4,
    clearcoat: 0.2,
    emissive: 0xff2a38,
    emissiveIntensity: 0.4,
    transparent: true,
    depthWrite: true,
  });

  const mesh = new Mesh(geometry, material);
  container.add(mesh);

  // Position from config (adapter will apply scenePosition)
  // Store original Y for hover animation
  const originalY = mesh.position.y;

  // Load texture asynchronously
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // GSAP timelines storage for cleanup
  const timelines = [];

  // Event handlers
  const handlers = {};

  // Hover effect (rise-in)
  handlers.hover = (enter) => {
    const targetY = enter ? originalY + 0.15 : originalY;
    const tl = gsap.to(mesh.position, {
      y: targetY,
      duration: 0.15,
      ease: 'power3.out',
    });
    timelines.push(tl);
  };

  // Click effect (press-down + emit)
  handlers.click = () => {
    const tl = gsap.to(mesh.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      ease: 'back.out',
    });
    timelines.push(tl);
    ctx.emit('hub-collection.select');
  };

  // Attach handlers to userData
  container.userData.handlers = handlers;

  // Cleanup routine
  container.userData.cleanup = () => {
    // Dispose geometry & material
    geometry.dispose();
    material.dispose();

    // Kill any GSAP timelines
    timelines.forEach((t) => t.kill());
    timelines.length = 0;

    // Remove handlers reference
    container.userData.handlers = {};
  };

  return container;
}
